import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"风险与停止条件","description":"Hearth 的主要风险、全局与阶段停止条件，以及不能删除的产品底线。","frontmatter":{"title":"风险与停止条件","description":"Hearth 的主要风险、全局与阶段停止条件，以及不能删除的产品底线。","outline":[2]},"headers":[],"relativePath":"reference/risks.md","filePath":"reference/risks.md","lastUpdated":1793863446000}'),l={name:"reference/risks.md"};function i(o,t,s,h,n,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="风险与停止条件" tabindex="-1">风险与停止条件 <a class="header-anchor" href="#风险与停止条件" aria-label="Permalink to &quot;风险与停止条件&quot;">​</a></h1><p class="lead">什么时候暂停、回退或缩小范围，比“继续加功能”更难，也更重要。这里列出的不是待办，而是已经出现时必须优先处理的信号。阶段可以慢一点，但不能在风险没有处理时继续往前推。</p><h2 id="主要风险与停止条件" tabindex="-1">主要风险与停止条件 <a class="header-anchor" href="#主要风险与停止条件" aria-label="Permalink to &quot;主要风险与停止条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>早期信号</th><th>应对</th></tr></thead><tbody><tr><td>范围膨胀</td><td>每个阶段都在加执行器，核心闭环还不稳定</td><td>用真实任务集和阶段出口控制范围</td></tr><tr><td>恢复不可靠</td><td>重启丢任务、重复发送、状态对不上</td><td>单写者、检查点、幂等、故障注入</td></tr><tr><td>安全失守</td><td>越权、凭据泄露、提示词注入成功</td><td>隔离、短期凭据、审批、拒绝路径测试</td></tr><tr><td>成本失控</td><td>单任务费用高，人工时间却没有下降</td><td>硬预算、上下文筛选、规则优先、停止优先</td></tr><tr><td>依赖外部执行器</td><td>对方升级后大量任务失败</td><td>版本锁定、适配层、降级和人工接管</td></tr><tr><td>维护负担过重</td><td>每周大量时间修依赖、渠道和环境</td><td>不重写底层、减少连接器、自动化升级测试</td></tr><tr><td>通知疲劳</td><td>用户关闭通知或长期忽略审批</td><td>注意力预算、聚合、静默和降频</td></tr><tr><td>记忆错误</td><td>反复引用过期、错误或越界的事实</td><td>来源、可信度、冲突、遗忘和用户纠正</td></tr><tr><td>方法进化漂移</td><td>流程越来越复杂，权限越来越多</td><td>评估、灰度、权限交集和回退</td></tr><tr><td>多设备分裂</td><td>重复执行、旧设备复活已删除内容</td><td>单一权威状态、版本、删除标记和设备撤销</td></tr><tr><td>产品像套壳</td><td>去掉 Codex 后没有独立价值</td><td>任务控制、审批、恢复、记忆和评估必须自研</td></tr><tr><td>用户信任下降</td><td>用户看不懂系统在做什么，也无法撤销</td><td>可解释状态、产物、回执、停止开关</td></tr></tbody></table><p>出现以下任一情况时，暂停新增功能，先修复问题：</p><ul><li>高风险动作发生越权；</li><li>凭据或敏感数据泄露；</li><li>故障注入出现重复外部副作用；</li><li>崩溃恢复率低于 95%；</li><li>用户无法撤销设备、连接或临时授权；</li><li>关键记忆无法被真正遗忘；</li><li>界面状态与事实记录不一致；</li><li>外部动作无法对账；</li><li>用户不知道为什么被提醒，或无法停止主动服务。</li></ul><p>每个阶段也有自己的停止条件。它们不是“代码写完了没有”，而是该阶段承诺的用户结果是否真的可靠。</p><table tabindex="0"><thead><tr><th>阶段</th><th>出现这些情况就不要进入下一阶段</th></tr></thead><tbody><tr><td>第一阶段 · 最小完整 MVP</td><td>无法定义并完成真实任务；浏览器无法走完创建、审批、恢复和取回产物；重复外部操作无法消除</td></tr><tr><td>第二阶段 · 日常内容工作</td><td>用户仍需反复补背景；来源权限不能收窄；文档、表格或网页结果无法验证；写入可能重复或无法核对</td></tr><tr><td>第三阶段 · 桌面操作</td><td>成功率低且无法接管；操作无法证明没有越权；失败会留下半完成的高风险状态</td></tr><tr><td>第四阶段 · 主动服务与手机入口</td><td>主动提醒造成疲劳；用户无法预测何时会被打扰；手机审批可重复使用；后台任务无法停止</td></tr><tr><td>第五阶段 · 记忆与能力进化</td><td>错误记忆持续造成返工；遗忘没有传播；方法评估可被挑选样本操纵；新方法扩大权限</td></tr><tr><td>第六阶段 · 多设备与长期运行</td><td>多设备重复执行或状态分裂；设备丢失无法撤销；迁移后数据不一致；用户无法独立退出</td></tr></tbody></table><p>如果完成第二阶段后仍没有稳定的真实日常任务，人工时间没有实质下降，或者维护成本持续超过可支配时间，应当缩小产品，而不是继续堆功能。安全边界达不到可接受水平、用户不愿把真实数据交给它、或者多设备复杂度吞掉单设备体验，也都是缩范围的信号。</p><h2 id="不能删掉的地基" tabindex="-1">不能删掉的地基 <a class="header-anchor" href="#不能删掉的地基" aria-label="Permalink to &quot;不能删掉的地基&quot;">​</a></h2><ul><li>可重建的事实记录和失败恢复；</li><li>外部动作的预览、审批、幂等和回执；</li><li>真实任务、失败样本和独立验证；</li><li>记忆的来源、纠正和遗忘；</li><li>低打扰的任务卡和注意力入口；</li><li>随时可用的暂停与人工接管；</li><li>权限边界、凭据隔离和停止开关。</li></ul><p>这些不是赶进度时可以删除的“以后再做”，而是产品成立的前提。任何阶段都不能用“先上线，之后再补”交换它们。</p>',12)])])}const b=d(l,[["render",i]]);export{_ as __pageData,b as default};
